      const [x,y,w,h]=view,lines=[];for(let gx=Math.ceil(x/step)*step;gx<x+w;gx+=step)lines.push(`<path d="M${gx} ${y}v${h}"/>`);for(let gy=Math.ceil(y/step)*step;gy<y+h;gy+=step)lines.push(`<path d="M${x} ${gy}h${w}"/>`);
