      draft.depth=Number($('#solidDepth').value);draft.model.plane=$('#solidPlane').value;
      if(draft.model.base||$('#solidBaseType').value!=='extrude'||Number($('#solidTwist').value)!==0||Number($('#solidScale').value)!==1)draft.model.base={type:$('#solidBaseType').value,angle:Number($('#solidAngle').value),twist:Number($('#solidTwist').value),scale:Number($('#solidScale').value)};
      if(draft.model.base?.type==='revolve'){if(draft.model.outline.some(p=>p[0]<0)){error('Revolve requires U ≥ 0: U is radius and V is axial height. Edit the profile first.');return false;}if(draft.model.features.some(f=>f.through)){error('Revolve needs finite-depth tools. Disable Through entire base depth on each existing feature.');return false;}}
      if(draft.model.constraints?.length){try{draft.model.outline=StudioSketch.solve(draft.model.outline,draft.model.constraints);profileMarkup();}catch(e){error(e.message);return false;}}
