      const info=geometry.userData;$('#solidMetrics').textContent=`Volume ${info.volumeMm3.toFixed(1)} mm³ · Surface ${info.areaMm2.toFixed(1)} mm² · ${info.triangles} triangles`;
      if(frame&&controls){const bounds=new T.Box3().setFromObject(preview),centre=bounds.getCenter(new T.Vector3()),size=bounds.getSize(new T.Vector3());const distance=Math.max(2,size.length()*1.7);controls.target.copy(centre);camera.position.copy(centre).add(new T.Vector3(.7,.8,1).normalize().multiplyScalar(distance));controls.update();}
