      document.querySelectorAll('[data-feature]').forEach(b=>b.onclick=()=>{active=+b.dataset.feature;listFeatures();featureFields()});
      document.querySelectorAll('[data-enable]').forEach(b=>b.onchange=()=>{features[+b.dataset.enable].enabled=b.checked;rebuild()});
