      $('#solidFeatureTitle').textContent='Edit feature '+(active+1);$('#sfName').value=f.name;$('#sfOperation').value=f.operation;$('#sfShape').value=f.shape;$('#sfThrough').checked=f.through;
      ['sfU','sfV','sfW'].forEach((id,i)=>$('#'+id).value=f.position[i]);['sfRU','sfRV','sfRW'].forEach((id,i)=>$('#'+id).value=f.rotation[i]);dimensionsFields();
