    $('#solidApplyVertices').onclick=()=>{const lines=$('#solidVertices').value.trim().split(/\n/);if(lines.length>64){exactProfileError=true;return error('Use up to 64 vertices.');}const points=lines.map(l=>l.trim().split(/[ ,;]+/).map(Number));const issue=StudioSolidModel.profileError(points);if(issue){exactProfileError=true;return error(issue);}draft.model.outline=points;vertex=-1;fitProfile();finish()};
    $('#solidResize').onclick=()=>{const w=Number($('#solidWidth').value),h=Number($('#solidHeight').value),points=draft.model.outline;if(points.length<3||![w,h].every(v=>Number.isFinite(v)&&v>=.1&&v<=5000))return error('Use valid width and height.');const xs=points.map(p=>p[0]),ys=points.map(p=>p[1]),ow=Math.max(...xs)-Math.min(...xs),oh=Math.max(...ys)-Math.min(...ys),cx=(Math.max(...xs)+Math.min(...xs))/2,cy=(Math.max(...ys)+Math.min(...ys))/2;if(!ow||!oh)return error('Complete a valid profile first.');draft.model.outline=points.map(([u,v])=>[+(cx+(u-cx)*w/ow).toFixed(3),+(cy+(v-cy)*h/oh).toFixed(3)]);fitProfile();profileMarkup();rebuild()};
    $('#solidGrid').onchange=profileMarkup;$('#solidDepth').onchange=()=>rebuild();$('#solidPlane').onchange=()=>rebuild();
    for(const id of ['solidBaseType','solidAngle','solidTwist','solidScale'])$('#'+id).onchange=()=>rebuild();
    function listConstraints(){const constraints=draft.model.constraints||[];$('#sketchConstraints').innerHTML=constraints.map((c,i)=>`<p>${esc(c.type)} · ${c.a+1}${c.b!==undefined?' → '+(c.b+1):''}${c.type==='length'?' · '+c.value+' mm':''}<button type="button" data-remove-constraint="${i}" aria-label="Remove constraint ${i+1}">×</button></p>`).join('')||'<p class="tiny">No constraints.</p>';document.querySelectorAll('[data-remove-constraint]').forEach(b=>b.onclick=()=>{draft.model.constraints.splice(+b.dataset.removeConstraint,1);listConstraints();rebuild();});}
    $('#addSketchConstraint').onclick=()=>{try{const type=$('#constraintType').value,a=Number($('#constraintA').value)-1,b=Number($('#constraintB').value)-1,points=draft.model.outline,c=type==='fixed'?{type,a,value:points[a]?[...points[a]]:[]}:{type,a,b,value:type==='length'?Number($('#constraintLength').value):0},constraints=[...(draft.model.constraints||[]),c],next=StudioSketch.solve(points,constraints),issue=StudioSolidModel.profileError(next);if(issue)throw Error(issue);draft.model.constraints=constraints;draft.model.outline=next;listConstraints();fitProfile();profileMarkup();rebuild();}catch(e){error(e.message);}};
