    $('#curveSketchEdge').onclick=()=>{try{if(draft.model.constraints?.length)throw Error('Clear constraints before adding curved-edge vertices.');const points=StudioSketch.curve(draft.model.outline,Number($('#curveEdge').value)-1,[Number($('#curveU').value),Number($('#curveV').value)],Number($('#curveSegments').value)),issue=StudioSolidModel.profileError(points);if(issue)throw Error(issue);draft.model.outline=points;vertex=-1;fitProfile();profileMarkup();rebuild();}catch(e){error(e.message);}};
    function listModifiers(){const modifiers=draft.model.modifiers||[];$('#solidModifiers').innerHTML=modifiers.map((m,i)=>`<p>${i+1}. ${m.type==='mirror'?'Mirror '+esc(m.axis):'Pattern ×'+m.count+' · '+m.step.join(', ')+' mm'} <button type="button" data-remove-modifier="${i}" aria-label="Remove modifier ${i+1}">×</button></p>`).join('');document.querySelectorAll('[data-remove-modifier]').forEach(b=>b.onclick=()=>{draft.model.modifiers.splice(+b.dataset.removeModifier,1);listModifiers();rebuild();});}
