    $('#addSolidMirror').onclick=()=>addModifier({type:'mirror',axis:$('#modifierAxis').value});$('#addSolidPattern').onclick=()=>addModifier({type:'pattern',count:Number($('#patternCount').value),step:['U','V','W'].map(a=>Number($('#pattern'+a).value))});
    for(const id of ['solidDraw','solidRemoveVertex']){const action=$('#'+id).onclick;$('#'+id).onclick=()=>{if(draft.model.constraints?.length)return error('Clear sketch constraints before changing the vertex topology.');action();};}
    document.querySelectorAll('[data-profile]').forEach(button=>{const action=button.onclick;button.onclick=()=>{if(draft.model.constraints?.length)return error('Clear sketch constraints before changing the profile preset.');action();};});
